# Generated by manage.py generate_test_cases.
"""Verify one result API and MCP endpoint always enforce live authorization."""

from __future__ import annotations

from datetime import timedelta
from typing import Any
from uuid import uuid4

from django.contrib.auth.models import Permission
from django.http import HttpResponse
from django.utils import timezone
from rest_framework.response import Response
from rest_framework.test import APIRequestFactory, force_authenticate

from bloomerp.models.files.file import File
from bloomerp.models.files.file_extraction import FileExtraction
from bloomerp.tests.base import (
    BloomerpAPIViewTestCase,
    BloomerpMcpViewTestCase,
    ExpectedResult,
    McpRequestScenario,
    RequestScenario,
)
from bloomerp.tests.models.files.test_file_extraction_model import (
    create_source,
    install_extraction_storage,
    store_document,
)
from bloomerp.views.api.files.file_extraction_result import FileExtractionResultView


class TestFileExtractionResultView(BloomerpAPIViewTestCase):
    """Use generated request scenarios for status, filtering and access contracts."""

    view_name = "api_file_extraction_result"
    auto_create_customers = False

    def extendedSetup(self) -> None:
        """Create one private ready result in storage that has no local filesystem path."""
        self.storage = install_extraction_storage(self)
        self.source = create_source()
        self.job = FileExtraction.objects.create(
            source_file=self.source, requested_by=self.admin_user
        )
        store_document(
            self.job,
            [
                {"id": 1, "page": 1, "section": "Intro", "text": "Private result"},
                {"id": 2, "page": 2, "section": "Body", "text": "Second page"},
            ],
        )

    def get_test_scenarios(self) -> list[RequestScenario]:
        """Read permitted results while rejecting invalid identities and unbounded inputs."""
        data = {"job_id": str(self.job.pk)}
        scenarios = [
            RequestScenario(
                name="Owner reads bounded results",
                method="POST",
                user=self.admin_user,
                data=data,
                content_type="application/json",
                expected=ExpectedResult(response_validators=self.ready_result),
            ),
            RequestScenario(
                name="Owner selects one page and section",
                method="POST",
                user=self.admin_user,
                data={**data, "page": 2, "section": "Body"},
                content_type="application/json",
                expected=ExpectedResult(response_validators=self.selected_result),
            ),
            RequestScenario(
                name="Anonymous result access is denied",
                method="POST",
                data=data,
                content_type="application/json",
                expected=ExpectedResult(status_code=401),
            ),
            RequestScenario(
                name="Another owner cannot discover the result",
                method="POST",
                user=self.normal_user,
                data=data,
                content_type="application/json",
                expected=ExpectedResult(
                    status_code=404, response_validators=self.no_private_content
                ),
            ),
            RequestScenario(
                name="Unknown result has the same not-found response",
                method="POST",
                user=self.admin_user,
                data={"job_id": str(uuid4())},
                content_type="application/json",
                expected=ExpectedResult(
                    status_code=404, response_validators=self.no_private_content
                ),
            ),
            RequestScenario(
                name="Deleted source makes its result inaccessible",
                method="POST",
                user=self.admin_user,
                data=data,
                content_type="application/json",
                prepare=self.delete_source,
                expected=ExpectedResult(
                    status_code=404, response_validators=self.no_private_content
                ),
            ),
            RequestScenario(
                name="Expiry removes content and returns terminal status",
                method="POST",
                user=self.admin_user,
                data=data,
                content_type="application/json",
                prepare=self.expire_result,
                expected=ExpectedResult(response_validators=self.expired_result),
            ),
            RequestScenario(
                name="GET cannot retrieve job bytes",
                user=self.admin_user,
                expected=ExpectedResult(status_code=405),
            ),
        ]
        for arguments in (
            {"limit": 0},
            {"limit": 101},
            {"page": 101},
            {"page": 0},
            {"sheet": "x" * 32},
            {"cursor": "x" * 2049},
            {"cell_range": "B2"},
            {"sheet": "Data", "cell_range": "A0:A1"},
            {"url": "https://invalid.example"},
        ):
            scenarios.append(
                RequestScenario(
                    name=f"Rejects invalid result selection {arguments}",
                    method="POST",
                    user=self.admin_user,
                    data={**data, **arguments},
                    content_type="application/json",
                    expected=ExpectedResult(status_code=400),
                )
            )
        return scenarios

    def ready_result(self, response: HttpResponse) -> bool:
        """Require untrusted-content labeling and bounded records without storage locators."""
        payload = response.json()
        return (
            payload["status"] == "succeeded"
            and payload["records"][0]["text"] == "Private result"
            and payload["content_is_untrusted"]
            and payload["next_cursor"] is None
            and self.job.result.name not in str(payload)
        )

    def selected_result(self, response: HttpResponse) -> bool:
        """Read only the page/section requested through the same result endpoint."""
        records = response.json()["records"]
        return len(records) == 1 and records[0]["text"] == "Second page"

    def no_private_content(self, response: HttpResponse) -> bool:
        """Denied status requests disclose neither text, manifest previews nor storage keys."""
        return all(
            secret not in response.content.decode()
            for secret in ("Private result", "Second page", self.job.result.name)
        )

    def delete_source(self, scenario: RequestScenario) -> None:
        """Remove the backing library record inside the scenario's rollback boundary."""
        File.objects.filter(pk=self.source.pk).delete()

    def expire_result(self, scenario: RequestScenario) -> None:
        """Move retention expiry into the past immediately before reading."""
        FileExtraction.objects.filter(pk=self.job.pk).update(
            expires_at=timezone.now() - timedelta(seconds=1)
        )

    def expired_result(self, response: HttpResponse) -> bool:
        """Terminal expiry omits text and clears stored summaries and ciphertext."""
        payload = response.json()
        return (
            payload["status"] == "expired"
            and payload["manifest"] == {}
            and "records" not in payload
            and not self.storage.exists(self.job.result.name)
        )

    def call_result(self, user: Any) -> Response:
        """Invoke the real view while allowing user permission changes between reads."""
        request = APIRequestFactory().post(
            "/", {"job_id": str(self.job.pk)}, format="json"
        )
        force_authenticate(request, user=user)
        return FileExtractionResultView.as_view()(request)

    def test_source_permission_revocation_blocks_every_subsequent_read(self) -> None:
        """An existing owner's result is denied after the real File permission is revoked."""
        self.job.requested_by = self.normal_user
        self.job.save(update_fields=["requested_by"])
        permission = Permission.objects.get(
            content_type__app_label="bloomerp",
            content_type__model="file",
            codename="view_file",
        )
        self.normal_user.user_permissions.add(permission)
        self.assertEqual(self.call_result(self.normal_user).status_code, 200)
        self.normal_user.user_permissions.remove(permission)
        self.normal_user = type(self.normal_user).objects.get(pk=self.normal_user.pk)
        response = self.call_result(self.normal_user)
        self.assertEqual(response.status_code, 404)
        self.assertNotIn("Private result", str(response.data))

    def test_queued_failed_and_unavailable_jobs_return_small_status_only(self) -> None:
        """All nonsuccessful states withhold cached summaries and result records."""
        for state in (
            FileExtraction.Status.QUEUED,
            FileExtraction.Status.RUNNING,
            FileExtraction.Status.FAILED,
            FileExtraction.Status.UNAVAILABLE,
            FileExtraction.Status.CANCELLED,
        ):
            with self.subTest(state=state):
                FileExtraction.objects.filter(pk=self.job.pk).update(
                    status=state, started_at=timezone.now()
                )
                response = self.call_result(self.admin_user)
                self.assertEqual(response.status_code, 200)
                self.assertEqual(response.data["status"], state)
                self.assertNotIn("records", response.data)
                self.assertEqual(response.data["manifest"], {})


class TestFileExtractionResultMcp(BloomerpMcpViewTestCase):
    """Read the same owner-scoped result through the actual MCP transport."""

    view_name = "api_file_extraction_result"

    def setUp(self) -> None:
        """Create a bounded successful result without another endpoint or service."""
        super().setUp()
        install_extraction_storage(self)
        self.source = create_source()
        self.job = FileExtraction.objects.create(
            source_file=self.source, requested_by=self.admin_user
        )
        store_document(self.job, [{"id": 1, "section": "Text", "text": "MCP result"}])

    def get_test_scenarios(self) -> list[McpRequestScenario]:
        """Verify structured success, cross-owner denial and signed-cursor validation."""
        return [
            McpRequestScenario(
                name="MCP returns bounded structured results",
                user=self.admin_user,
                arguments={"job_id": str(self.job.pk)},
                expected=ExpectedResult(
                    response_validators=[self.mcp_is_error(False), self.valid_result]
                ),
            ),
            McpRequestScenario(
                name="MCP refuses cross-owner reads",
                user=self.normal_user,
                arguments={"job_id": str(self.job.pk)},
                expected=ExpectedResult(response_validators=self.mcp_is_error()),
            ),
            McpRequestScenario(
                name="MCP rejects a forged continuation",
                user=self.admin_user,
                arguments={"job_id": str(self.job.pk), "cursor": "forged"},
                expected=ExpectedResult(response_validators=self.mcp_is_error()),
            ),
        ]

    def valid_result(self, response: HttpResponse) -> bool:
        """Check extracted text remains explicitly untrusted structured tool data."""
        payload = response.json()["result"]["structuredContent"]
        return (
            payload["records"][0]["text"] == "MCP result"
            and payload["content_is_untrusted"]
            and payload["status"] == "succeeded"
        )
